import SwiftUI

/// The interim JK monogram (docs/design/brand/jk-monogram.svg): a J and K
/// ligature sharing one stem. One vector, drawn in a 100-unit square and
/// scaled to fit. Used for the JK tab fallback, the letter signature,
/// milestone letters, empty states and the opening animation.
struct MonogramShape: Shape {
    /// Generated by scripts/monogram.py; keep identical to the SVG.
    static let pathData = "M 34 15.5 L 44 15.5 L 44 63.5 C 44 78.5 37 87.5 25 87.5 C 18 87.5 13 83.5 13 78.5 C 13 74.5 16 71.5 20 71.5 C 24 71.5 27 74.5 27 78.5 C 31 77.5 34 72.5 34 63.5 Z M 24 12.5 L 54 12.5 L 54 15.5 C 48 15.5 45 16.5 44 18.5 L 34 18.5 C 33 16.5 30 15.5 24 15.5 Z M 44 49.5 L 70.5 15.5 L 75 15.5 L 44 55.5 Z M 65 12.5 L 82 12.5 L 82 15.5 L 65 15.5 Z M 51 42 L 57 34.5 L 83 69.5 L 72 69.5 Z M 67 66.5 L 87 66.5 L 87 69.5 L 67 69.5 Z"

    private static let unitPath: Path = parse(pathData)

    func path(in rect: CGRect) -> Path {
        let side = min(rect.width, rect.height)
        let scale = side / 100
        let transform = CGAffineTransform(translationX: rect.midX - side / 2, y: rect.midY - side / 2)
            .scaledBy(x: scale, y: scale)
        return Self.unitPath.applying(transform)
    }

    /// Absolute M, L, C and Z commands, as scripts/monogram.py writes them.
    private static func parse(_ data: String) -> Path {
        var path = Path()
        let tokens = data.split(separator: " ")
        var i = 0
        func num() -> CGFloat {
            defer { i += 1 }
            return CGFloat(Double(tokens[i]) ?? 0)
        }
        while i < tokens.count {
            let cmd = tokens[i]
            i += 1
            switch cmd {
            case "M": path.move(to: CGPoint(x: num(), y: num()))
            case "L": path.addLine(to: CGPoint(x: num(), y: num()))
            case "C":
                let c1 = CGPoint(x: num(), y: num())
                let c2 = CGPoint(x: num(), y: num())
                path.addCurve(to: CGPoint(x: num(), y: num()), control1: c1, control2: c2)
            case "Z": path.closeSubpath()
            default: break
            }
        }
        return path
    }
}

/// The monogram filled in champagne (JK's colour), decorative by default.
struct Monogram: View {
    var size: CGFloat = 44
    var color: Color = JK.accent

    var body: some View {
        MonogramShape()
            .fill(color)
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }
}

/// The brand device: a 2pt champagne rule.
struct BrandRule: View {
    var width: CGFloat? = 32

    var body: some View {
        Rectangle()
            .fill(JK.accent)
            .frame(width: width, height: JK.Size.rule)
            .frame(maxWidth: width == nil ? .infinity : nil, alignment: .leading)
            .accessibilityHidden(true)
    }
}

/// The JK mark (Home, Membership): the monogram, unboxed.
struct JKMark: View {
    var size: CGFloat = 56

    var body: some View {
        Monogram(size: size)
    }
}
